const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let actor=null, project=null, view='overview';const trackedRuns=new Set();
const key=()=>crypto.randomUUID();
async function api(path,options={}){options.headers={"Content-Type":"application/json",...(options.headers||{})};const r=await fetch(path,options);let data;try{data=await r.json()}catch{data={detail:'Unexpected response'}}if(!r.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));if(r.status===202&&data.status==='QUEUED'&&data.ai_run_id&&!trackedRuns.has(data.ai_run_id)){trackedRuns.add(data.ai_run_id);setTimeout(()=>trackAI(data.ai_run_id).catch(e=>toast(e.message,true)),0)}return data}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.style.background=error?'#a42828':'#17221c';t.hidden=false;setTimeout(()=>t.hidden=true,3500)}
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function trackAI(runId){trackedRuns.add(runId);while(true){const run=await api(`/api/projects/${project.id}/ai-runs/${runId}`);if($('#ai-run-status'))$('#ai-run-status').innerHTML=`<span class="tag">${esc(run.operation.replaceAll('_',' '))} · ${esc(run.status)}</span>`;if(['COMPLETED','FAILED'].includes(run.status)){trackedRuns.delete(runId);const result=run.result||{};toast(run.status==='FAILED'?`${run.failure_code}: ${result.message||'AI run failed'}`:`${run.operation.replaceAll('_',' ')} completed`,run.status==='FAILED');await render();return run}await pause(3000)}}
async function startAI(path,body){const run=await api(path,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(body)});toast(`${run.operation.replaceAll('_',' ')} queued. You may leave this page.`);return run}
function requirePasswordChange(){actor=null;$('#login').hidden=true;$('#projects').hidden=true;$('#workspace').hidden=true;$('#password-change').hidden=false}
async function boot(){try{actor=await api('/api/auth/me');actor.must_change_password?requirePasswordChange():showProjects()}catch{$('#login').hidden=false}}
$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{actor=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});$('#login').hidden=true;actor.must_change_password?requirePasswordChange():showProjects()}catch(x){toast(x.message,true)}};
$('#password-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/password',{method:'POST',body:JSON.stringify(body)});actor=await api('/api/auth/me');$('#password-change').hidden=true;toast('Password changed. Workspace access unlocked.');showProjects()}catch(x){toast(x.message,true)}};
async function showProjects(){project=null;$('#workspace').hidden=true;$('#projects').hidden=false;$('#identity').innerHTML=`${esc(actor.display_name)} <button class="link" id="logout">Sign out</button>`;$('#logout').onclick=async()=>{await api('/api/auth/logout',{method:'POST'});location.reload()};const rows=await api('/api/projects');$('#project-list').innerHTML=rows.length?rows.map(p=>`<article class="card"><span class="tag">${esc(p.role)}</span><h2>${esc(p.name)}</h2><p>${esc(p.objective)}</p><button data-open="${esc(p.id)}">Open workspace</button></article>`).join(''):'<article class="card"><h2>No projects yet</h2><p class="muted">Create a project, then give OIDA the context it needs.</p></article>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openProject(b.dataset.open))}
$('#new-project').onclick=()=>modal(`<h2>Create project</h2><label>Project name<input name="name" required minlength="2"></label><label>Objective<textarea name="objective" required minlength="10"></textarea></label><label>Description<textarea name="description"></textarea></label>`,async f=>{const p=await api('/api/projects',{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});await openProject(p.id)});
$('#back').onclick=showProjects;document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));render()});
async function openProject(id){project=await api(`/api/projects/${id}`);$('#projects').hidden=true;$('#workspace').hidden=false;view='overview';document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.view==='overview'));const runs=await api(`/api/projects/${project.id}/async-ai-runs`);runs.filter(x=>['QUEUED','RUNNING'].includes(x.status)).forEach(x=>trackAI(x.id).catch(e=>toast(e.message,true)));await render()}
async function render(){if(!project)return;let active=[];try{active=(await api(`/api/projects/${project.id}/async-ai-runs`)).filter(x=>['QUEUED','RUNNING'].includes(x.status))}catch{}$('#workspace-head').innerHTML=`<p class="eyebrow">Project workspace</p><h1>${esc(project.name)}</h1><p>${esc(project.objective)}</p><div id="ai-run-status">${active.map(x=>`<span class="tag">${esc(x.operation.replaceAll('_',' '))} · ${esc(x.status)}</span>`).join('')}</div>`;try{if(view==='overview')await overview();if(view==='integrations')await integrationsView();if(view==='context')await contextView();if(view==='requirements')await requirementsView();if(view==='solution')await solutionView();if(view==='delivery')await deliveryView();if(view==='execution')await executionView();if(view==='validation')await validationView();if(view==='acceptance')await acceptanceView();if(view==='audit')await auditView()}catch(e){$('#view').innerHTML=`<div class="card"><h2>Unable to load</h2><p>${esc(e.message)}</p></div>`}}
async function integrationsView(){
  const r=await api(`/api/projects/${project.id}/integrations/readiness`),sources=await api(`/api/projects/${project.id}/integrations/document-again/sources`);
  let available=[];if(['READY','PARTIAL','STALE'].includes(r.document_again.status)){try{available=await api(`/api/projects/${project.id}/integrations/document-again/documents`)}catch{available=[]}}
  const card=(name,x)=>`<article class="card"><span class="tag ${['ERROR','INVALID','STALE'].includes(x.status)?'red':''}">${esc(x.status)}</span><h2>${name}</h2><p>${esc(x.live_configuration||'Binding recorded')}</p></article>`;
  $('#view').innerHTML=`<section><p class="eyebrow">Project settings</p><h1>Integrations</h1><p>Connect authoritative sources deliberately. OIDA never imports or writes automatically.</p><div class="grid">${card('Document Again',r.document_again)}${card('PM Again',r.pm_again)}</div>${r.pm_again.status==='UNBOUND'?'<button id="bind-pm">Bind PM Again project</button>':''}</section><section class="section"><div class="split"><div><h2>Available documents</h2><p class="muted">Select exact external documents to add to Project Context.</p></div>${r.document_again.status==='UNBOUND'?'<button id="bind-doc">Bind Document Again</button>':'<button id="refresh-doc">Refresh metadata</button>'}</div><div class="grid">${available.map(x=>`<article class="card"><span class="tag">REV ${esc(x.revision_number||x.revision_id)}</span><h3>${esc(x.title)}</h3><button data-import-doc="${esc(x.id)}">Import revision</button></article>`).join('')||'<article class="card"><p>No selectable documents are available.</p></article>'}</div></section><section class="section"><h2>Imported provenance</h2><div class="grid">${sources.map(x=>`<article class="card"><span class="tag ${x.status==='READY'?'':'red'}">${esc(x.status)}</span><h3>${esc(x.external_document_title)}</h3><p>Revision ${esc(x.external_revision_id)}</p><small>SHA-256 ${esc(x.content_sha256)}${x.newer_than_requirement_baseline?' · newer than baseline':''}</small></article>`).join('')||'<article class="card"><p>No imported document revisions.</p></article>'}</div></section>`;
  if($('#bind-doc'))$('#bind-doc').onclick=()=>modal('<h2>Bind Document Again project</h2><p>OIDA verifies the external project before marking the binding READY.</p><label>External project ID<input name="external_project_id" required></label>',async f=>{await api(`/api/projects/${project.id}/integrations/document-again/binding`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});render()});
  if($('#refresh-doc'))$('#refresh-doc').onclick=async()=>{const x=await api(`/api/projects/${project.id}/integrations/document-again:refresh`,{method:'POST'});toast(`${x.checked} source(s) checked; ${x.attention} need attention.`,x.attention>0);render()};
  if($('#bind-pm'))$('#bind-pm').onclick=()=>modal('<h2>Bind PM Again project</h2><p>The project is read back before the binding becomes READY.</p><label>External project ID or slug<input name="external_project_id" required></label>',async f=>{const b=await api(`/api/projects/${project.id}/execution/bindings/pm-again`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});const v=await api(`/api/projects/${project.id}/execution/bindings/${b.id}:verify`,{method:'POST'});toast(`PM Again binding ${v.status}.`,v.status!=='READY');render()});
  document.querySelectorAll('[data-import-doc]').forEach(b=>b.onclick=async()=>{await api(`/api/projects/${project.id}/integrations/document-again/import`,{method:'POST',body:JSON.stringify({document_id:b.dataset.importDoc})});toast('Exact document revision imported into Project Context.');render()})
}
async function overview(){const t=await api(`/api/projects/${project.id}/truth`);const attention=t.attention.map(a=>`<article class="card attention ${a.severity==='HIGH'?'high':''}"><span class="tag ${a.severity==='HIGH'?'red':'warn'}">${esc(a.type)}</span><p>${esc(a.message)}</p></article>`).join('')||'<article class="card"><p>No human attention is currently required.</p></article>';const execution=t.execution_materialization_progress||{materialized:0,total:0},validation=t.validation||{pass:0,total:0};$('#view').innerHTML=`<div class="stats"><div class="stat"><small>Context</small><strong>${t.context.source_count}</strong><span>revision ${t.context.revision}</span></div><div class="stat"><small>Requirements</small><strong>${t.requirements.committed_count}</strong><span>${esc(t.baseline.status)}</span></div><div class="stat"><small>Gate 2</small><strong class="${t.delivery_readiness==='GATE_2_COMPLETE'?'truth-ok':'truth-blocked'}">${esc(t.delivery_baseline.status)}</strong><span>${esc(t.delivery_readiness)}</span></div><div class="stat"><small>Execution</small><strong>${execution.materialized}/${execution.total}</strong><span>${esc(t.execution_health||'NOT READY')}</span></div><div class="stat"><small>Validation</small><strong>${validation.pass}/${validation.total}</strong><span>${esc(t.qa_scope_status||'NOT COMMITTED')}</span></div><div class="stat"><small>Gate 3</small><strong class="${t.gate3_status==='ACCEPTED'?'truth-ok':'truth-blocked'}">${esc(t.gate3_status||'NOT ACCEPTED')}</strong><span>${esc(t.acceptance_readiness||'BLOCKED')}</span></div></div><section class="section"><h2>Needs your attention</h2><div class="grid">${attention}</div></section>${t.next_recommended_phase?`<section class="card section"><h2>Next useful action</h2><p><code>${esc(t.next_recommended_phase)}</code></p></section>`:''}`}
async function contextView(){const c=await api(`/api/projects/${project.id}/context`);$('#view').innerHTML=`<div class="split"><div><h2>Project context</h2><p class="muted">Authoritative user sources · revision ${c.context_revision}</p></div><div class="actions"><button id="add-context">Add context</button><button id="analyze" ${c.items.length?'':'disabled'}>Analyze project context</button></div></div><div class="section grid">${c.items.map(i=>`<article class="card"><span class="tag">${esc(i.source_type)}</span><span class="tag">v${i.version}</span><h3>${esc(i.title)}</h3><div class="context-content">${esc(i.content)}</div><button class="secondary" data-edit-context="${i.id}">Edit</button></article>`).join('')||'<article class="card"><p>Add pasted project material before running AI analysis.</p></article>'}</div>`;$('#add-context').onclick=()=>contextModal();if($('#analyze'))$('#analyze').onclick=()=>generationModal();document.querySelectorAll('[data-edit-context]').forEach(b=>b.onclick=()=>contextModal(c.items.find(i=>i.id===b.dataset.editContext)))}
function contextModal(item){modal(`<h2>${item?'Edit':'Add'} context</h2>${item?'':`<label>Source type<select name="source_type"><option>PASTED_TEXT</option><option>USER_NOTE</option><option>DOCUMENT</option></select></label>`}<label>Title<input name="title" required value="${esc(item?.title||'')}"></label><label>Content<textarea name="content" required>${esc(item?.content||'')}</textarea></label>`,async f=>{const body=Object.fromEntries(f);if(item)await api(`/api/projects/${project.id}/context/${item.id}`,{method:'PATCH',body:JSON.stringify(body)});else await api(`/api/projects/${project.id}/context`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(body)});toast('Context saved; previous pending AI work may now be stale.');render()})}
function generationModal(candidate){modal(`<h2>${candidate?'Regenerate candidate':'Analyze project context'}</h2><p>OIDA will create structured candidates, never committed requirements.</p><label>Optional guidance<textarea name="instruction" placeholder="Generate concise, implementation-neutral requirements."></textarea></label>`,async f=>{const path=candidate?`/api/projects/${project.id}/requirement-candidates/${candidate}:regenerate`:`/api/projects/${project.id}/ai/requirements:generate`;if(candidate){await api(path,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});render()}else await startAI(path,Object.fromEntries(f))})}
async function requirementsView(){const [cs,rs,ready,bs]=await Promise.all([api(`/api/projects/${project.id}/requirement-candidates`),api(`/api/projects/${project.id}/requirements`),api(`/api/projects/${project.id}/requirement-baselines/readiness`),api(`/api/projects/${project.id}/requirement-baselines`)]);const candidates=cs.map(c=>`<article class="card candidate ${c.stale?'stale':''} ${c.status==='REJECTED'?'rejected':''}"><div class="card-head"><div><span class="tag">AI ${esc(c.status)}</span>${c.stale?'<span class="tag warn">STALE</span>':''}${c.human_modified?'<span class="tag">HUMAN MODIFIED</span>':''}</div><span>${esc(c.priority)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.statement)}</p><p class="muted">${esc(c.rationale)}</p><ul class="criteria">${c.acceptance_criteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><strong>Sources:</strong> ${c.source_ids.map(esc).join(', ')}</p>${c.gaps.length?`<p><strong>Gaps:</strong> ${c.gaps.map(esc).join('; ')}</p>`:''}<div class="actions">${c.status==='NEEDS_REVIEW'?`<button data-accept="${c.id}" ${c.stale?'disabled':''}>Accept</button><button class="secondary" data-edit="${c.id}">Edit</button><button class="warning" data-regenerate="${c.id}">Regenerate</button><button class="danger" data-reject="${c.id}">Reject</button>`:''}</div></article>`).join('')||'<article class="card"><p>No AI candidates yet. Add context and ask OIDA to analyze it.</p></article>';const reqs=rs.map(r=>`<article class="card"><div class="card-head"><span class="tag">${esc(r.requirement_code)} · COMMITTED</span><span>revision ${r.current_revision}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.statement)}</p><p class="muted">Origin: ${esc(r.origin)}</p><button class="secondary" data-edit-req="${r.id}">Edit working revision</button></article>`).join('')||'<article class="card"><p>No committed requirements.</p></article>';const latest=bs[0];$('#view').innerHTML=`<section><div class="split"><div><h2>AI candidates</h2><p class="muted">Reviewable proposals are separate from committed truth.</p></div><button id="run-ai">Analyze context</button></div><div class="grid">${candidates}</div></section><section class="section"><div class="split"><div><h2>Committed requirements</h2><p class="muted">Stable, human-controlled project truth.</p></div><button id="manual">Add manual requirement</button></div><div class="grid">${reqs}</div></section><section class="card section"><h2>Requirement baseline · Gate 1</h2>${latest?`<p><strong class="truth-ok">v${latest.version} — FROZEN</strong> · ${latest.requirement_count} exact requirement revisions · ${esc(latest.frozen_at)}</p>`:`<p>${ready.committed_requirement_count} committed requirements · ${ready.pending_candidate_count} candidates still need review · ${ready.blocking_items.length?ready.blocking_items.map(esc).join(', '):'0 blocking validation issues'}</p><button id="freeze" ${ready.ready?'':'disabled'}>Freeze baseline</button>`}</section>`;bindRequirementActions(cs,rs,ready)}
function bindRequirementActions(cs,rs,ready){$('#run-ai').onclick=()=>generationModal();$('#manual').onclick=()=>requirementModal();document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{await api(`/api/projects/${project.id}/requirement-candidates/${b.dataset.accept}:accept`,{method:'POST',headers:{'Idempotency-Key':key()}});toast('Candidate committed and readback confirmed.');render()}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>modal('<h2>Reject candidate</h2><label>Optional reason<textarea name="reason"></textarea></label>',async f=>{await api(`/api/projects/${project.id}/requirement-candidates/${b.dataset.reject}:reject`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});render()}));document.querySelectorAll('[data-regenerate]').forEach(b=>b.onclick=()=>generationModal(b.dataset.regenerate));document.querySelectorAll('[data-edit]').forEach(b=>candidateModal(cs.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-edit-req]').forEach(b=>requirementModal(rs.find(x=>x.id===b.dataset.editReq)));if($('#freeze'))$('#freeze').onclick=async()=>{if(!confirm(`Freeze Requirement Baseline v1 with ${ready.committed_requirement_count} requirements? This snapshot cannot be changed.`))return;try{const r=await api(`/api/projects/${project.id}/requirement-baselines:freeze`,{method:'POST',headers:{'Idempotency-Key':key()}});toast(`Baseline v${r.version} frozen; membership confirmed.`);render()}catch(e){toast(e.message,true)}}}
function candidateModal(c){modal(`<h2>Edit AI candidate</h2><p>The original AI output remains in audit history.</p><label>Title<input name="title" value="${esc(c.title)}" required></label><label>Statement<textarea name="statement" required>${esc(c.statement)}</textarea></label><label>Rationale<textarea name="rationale" required>${esc(c.rationale)}</textarea></label><label>Priority<select name="priority">${['MUST','SHOULD','COULD'].map(x=>`<option ${c.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Acceptance criteria (one per line)<textarea name="criteria" required>${esc(c.acceptance_criteria.join('\n'))}</textarea></label>`,async f=>{const x=Object.fromEntries(f);x.acceptance_criteria=x.criteria.split('\n').filter(Boolean);delete x.criteria;await api(`/api/projects/${project.id}/requirement-candidates/${c.id}`,{method:'PATCH',body:JSON.stringify(x)});render()})}
function requirementModal(r){modal(`<h2>${r?'Edit working revision':'Add manual requirement'}</h2><label>Title<input name="title" value="${esc(r?.title||'')}" required></label><label>Statement<textarea name="statement" required>${esc(r?.statement||'')}</textarea></label><label>Rationale<textarea name="rationale" required>${esc(r?.rationale||'')}</textarea></label><label>Priority<select name="priority">${['MUST','SHOULD','COULD'].map(x=>`<option ${r?.priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Acceptance criteria (one per line)<textarea name="criteria" required>${esc((r?.acceptance_criteria||[]).join('\n'))}</textarea></label>`,async f=>{const x=Object.fromEntries(f);x.acceptance_criteria=x.criteria.split('\n').filter(Boolean);delete x.criteria;if(r)await api(`/api/projects/${project.id}/requirements/${r.id}`,{method:'PATCH',body:JSON.stringify(x)});else await api(`/api/projects/${project.id}/requirements`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(x)});render()})}

async function solutionView(){const [ready,candidates,solutions]=await Promise.all([api(`/api/projects/${project.id}/solution-readiness`),api(`/api/projects/${project.id}/solution-candidates`),api(`/api/projects/${project.id}/solutions`)]);const active=candidates.filter(x=>['NEEDS_REVIEW','SELECTED'].includes(x.status));const cards=candidates.map(c=>`<article class="card candidate ${c.stale?'stale':''}"><div class="card-head"><div><input type="checkbox" data-merge-choice="${c.id}" ${!['NEEDS_REVIEW','SELECTED'].includes(c.status)?'disabled':''}> <span class="tag">${esc(c.status)}</span>${c.recommended?'<span class="tag warn">RECOMMENDED</span>':''}${c.stale?'<span class="tag red">STALE</span>':''}</div><span>${esc(c.content.complexity)} · ${esc(c.content.effort)}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><p><strong>Components:</strong> ${c.content.components.map(x=>esc(x.name)).join(', ')}</p><p><strong>Pros:</strong> ${c.content.pros.map(esc).join('; ')}</p><p><strong>Cons:</strong> ${c.content.cons.map(esc).join('; ')}</p><p><strong>Coverage:</strong> ${c.content.requirement_coverage.filter(x=>x.status==='COVERED').length}/${c.content.requirement_coverage.length}</p><div class="actions">${['NEEDS_REVIEW','SELECTED'].includes(c.status)?`<button data-select-solution="${c.id}" ${c.stale?'disabled':''}>${c.status==='SELECTED'?'Selected':'Select'}</button><button class="secondary" data-edit-solution="${c.id}">Edit</button><button class="warning" data-regen-solution="${c.id}">Regenerate</button><button class="danger" data-reject-solution="${c.id}">Reject</button>${c.status==='SELECTED'?`<button data-commit-solution="${c.id}">Commit solution</button>`:''}`:''}</div></article>`).join('')||'<article class="card"><p>No solution alternatives yet.</p></article>';const committed=solutions.map(x=>`<article class="card"><div class="card-head"><span class="tag">${esc(x.solution_code)} · COMMITTED</span><span>revision ${x.current_revision}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p>${x.stale?'<p class="truth-blocked">Stale against the latest Requirement Baseline.</p>':''}</article>`).join('');$('#view').innerHTML=`<section><div class="split"><div><h2>Solution alternatives</h2><p class="muted">AI proposals remain non-authoritative until you select and commit one.</p></div><div class="actions"><button id="generate-solutions" ${ready.ready?'':'disabled'}>Generate alternatives</button><button id="compare-solutions" ${active.length<2?'disabled':''}>Compare</button><button id="merge-solutions" ${active.length<2?'disabled':''}>Merge checked</button></div></div>${!ready.ready?'<article class="card"><p>Freeze Gate 1 before solution generation.</p></article>':''}<div class="section grid">${cards}</div></section><section class="section"><h2>Committed solution</h2>${committed||'<article class="card"><p>Select and commit one reviewed alternative.</p></article>'}</section>`;bindSolutionActions(candidates)}
function bindSolutionActions(candidates){$('#generate-solutions').onclick=()=>designGenerationModal('solutions');$('#compare-solutions').onclick=()=>compareSolutions(candidates.filter(x=>['NEEDS_REVIEW','SELECTED'].includes(x.status)));$('#merge-solutions').onclick=async()=>{const ids=[...document.querySelectorAll('[data-merge-choice]:checked')].map(x=>x.dataset.mergeChoice);if(ids.length<2)return toast('Check at least two alternatives to merge.',true);try{await api(`/api/projects/${project.id}/solution-candidates:merge`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify({candidate_ids:ids,title:'Human composite solution'})});toast('Merged candidate created for review.');render()}catch(e){toast(e.message,true)}};document.querySelectorAll('[data-select-solution]').forEach(b=>b.onclick=async()=>{await api(`/api/projects/${project.id}/solution-candidates/${b.dataset.selectSolution}:select`,{method:'POST'});render()});document.querySelectorAll('[data-edit-solution]').forEach(b=>b.onclick=()=>structuredEditor('Edit solution candidate',candidates.find(x=>x.id===b.dataset.editSolution).content,async content=>api(`/api/projects/${project.id}/solution-candidates/${b.dataset.editSolution}`,{method:'PATCH',body:JSON.stringify({content})})));document.querySelectorAll('[data-regen-solution]').forEach(b=>b.onclick=()=>designGenerationModal('solutions',b.dataset.regenSolution));document.querySelectorAll('[data-reject-solution]').forEach(b=>b.onclick=()=>modal('<h2>Reject solution alternative</h2><label>Reason<textarea name="reason"></textarea></label>',async f=>{await api(`/api/projects/${project.id}/solution-candidates/${b.dataset.rejectSolution}:reject`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});render()}));document.querySelectorAll('[data-commit-solution]').forEach(b=>b.onclick=async()=>{if(!confirm('Commit this exact solution revision?'))return;await api(`/api/projects/${project.id}/solution-candidates/${b.dataset.commitSolution}:commit`,{method:'POST',headers:{'Idempotency-Key':key()}});toast('Solution committed and readback confirmed.');render()})}
function designGenerationModal(kind,candidate){const isSolution=kind==='solutions';modal(`<h2>${candidate?'Regenerate':'Generate'} ${isSolution?'solution alternatives':'delivery plan'}</h2><p>AI output will be structured, grounded, and non-authoritative.</p><label>Optional guidance<textarea name="instruction"></textarea></label>`,async f=>{const path=isSolution?(candidate?`/api/projects/${project.id}/solution-candidates/${candidate}:regenerate`:`/api/projects/${project.id}/ai/solutions:generate`):(candidate?`/api/projects/${project.id}/delivery-plan-candidates/${candidate}:regenerate`:`/api/projects/${project.id}/ai/delivery-plans:generate`);if(candidate){await api(path,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});render()}else await startAI(path,Object.fromEntries(f))})}
function compareSolutions(candidates){const rows=[['Criterion',...candidates.map(x=>x.title)],['Complexity',...candidates.map(x=>x.content.complexity)],['Effort',...candidates.map(x=>x.content.effort)],['Confidence',...candidates.map(x=>x.content.confidence)],['Pros',...candidates.map(x=>x.content.pros.join('; '))],['Cons',...candidates.map(x=>x.content.cons.join('; '))],['Risks',...candidates.map(x=>x.content.risks.join('; '))],['Recommendation',...candidates.map(x=>x.recommended?x.content.recommendation_basis:'—')]];modal(`<h2>Compare alternatives</h2><div class="table-wrap"><table>${rows.map((r,i)=>`<tr>${r.map(x=>`<${i?'td':'th'}>${esc(x)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div>`,async()=>{})}
function structuredEditor(title,content,save){modal(`<h2>${esc(title)}</h2><p class="muted">Structured refs, coverage, and provenance are validated by the server.</p><label>Structured content<textarea name="content" class="json-editor" required>${esc(JSON.stringify(content,null,2))}</textarea></label>`,async f=>{let parsed;try{parsed=JSON.parse(f.get('content'))}catch{throw new Error('Content must be valid JSON.')}await save(parsed);toast('Revision saved.');render()})}

async function deliveryView(){const [candidates,plans,ready,baselines,solutions]=await Promise.all([api(`/api/projects/${project.id}/delivery-plan-candidates`),api(`/api/projects/${project.id}/delivery-plans`),api(`/api/projects/${project.id}/delivery-baselines/readiness`),api(`/api/projects/${project.id}/delivery-baselines`),api(`/api/projects/${project.id}/solutions`)]);const cards=candidates.map(c=>`<article class="card candidate ${c.stale?'stale':''}"><div class="card-head"><div><span class="tag">${esc(c.status)}</span>${c.human_modified?'<span class="tag">HUMAN MODIFIED</span>':''}${c.stale?'<span class="tag red">STALE</span>':''}</div><span>revision ${c.current_revision}</span></div><h3>${esc(c.title)}</h3><p>${esc(c.content.planning_summary)}</p><h4>Delivery items</h4>${c.content.items.map(i=>`<div class="subitem"><strong>${esc(i.ref)} · ${esc(i.title)}</strong><small>${esc(i.workstream_ref)} · ${esc(i.owner_role)} · ${esc(i.effort)}</small>${c.status==='NEEDS_REVIEW'?`<button class="link danger" data-remove-item="${c.id}|${esc(i.ref)}">Remove</button>`:''}</div>`).join('')}<p><strong>Milestones:</strong> ${c.content.milestones.map(x=>esc(x.title)).join(', ')}</p><p><strong>Dependencies:</strong> ${c.content.dependencies.length}</p><div class="actions">${c.status==='NEEDS_REVIEW'?`<button class="secondary" data-edit-plan="${c.id}">Edit structure</button><button class="secondary" data-add-item="${c.id}">Add item</button><button class="secondary" data-edit-deps="${c.id}">Dependencies</button><button class="warning" data-regen-plan="${c.id}">Regenerate</button><button class="danger" data-reject-plan="${c.id}">Reject</button><button data-commit-plan="${c.id}" ${c.stale?'disabled':''}>Commit plan</button>`:''}</div></article>`).join('')||'<article class="card"><p>No delivery-plan candidate yet.</p></article>';const committed=plans.map(p=>`<article class="card"><span class="tag">${esc(p.plan_code)} · COMMITTED</span><h3>${esc(p.title)}</h3><p>${p.content.items.length} items · ${p.content.milestones.length} milestones · ${p.content.dependencies.length} dependencies</p>${p.stale?'<p class="truth-blocked">Plan is stale.</p>':''}</article>`).join('');const frozen=baselines[0];$('#view').innerHTML=`<section><div class="split"><div><h2>Delivery design</h2><p class="muted">Plan from the exact committed solution revision.</p></div><button id="generate-plan" ${solutions.length?'':'disabled'}>Generate delivery plan</button></div><div class="section grid">${cards}</div></section><section class="section"><h2>Committed delivery plan</h2>${committed||'<article class="card"><p>Review and commit a plan candidate.</p></article>'}</section><section class="card section"><h2>Delivery Baseline · Gate 2</h2>${frozen?`<p><strong class="truth-ok">v${frozen.version} — FROZEN</strong></p><p>Requirement Baseline: ${esc(frozen.requirement_baseline_id)}<br>Solution revision: ${esc(frozen.solution_revision_id)}<br>Plan revision: ${esc(frozen.delivery_plan_revision_id)}</p>`:`<p>${ready.blocking_items.length?ready.blocking_items.map(esc).join(', '):'All deterministic checks pass.'}</p><button id="freeze-gate2" ${ready.ready?'':'disabled'}>Freeze Delivery Baseline</button>`}</section>`;bindDeliveryActions(candidates,ready)}
function bindDeliveryActions(candidates,ready){$('#generate-plan').onclick=()=>designGenerationModal('plans');document.querySelectorAll('[data-edit-plan]').forEach(b=>b.onclick=()=>structuredEditor('Edit delivery plan',candidates.find(x=>x.id===b.dataset.editPlan).content,async content=>api(`/api/projects/${project.id}/delivery-plan-candidates/${b.dataset.editPlan}`,{method:'PATCH',body:JSON.stringify({content})})));document.querySelectorAll('[data-add-item]').forEach(b=>b.onclick=()=>addItemModal(b.dataset.addItem,candidates.find(x=>x.id===b.dataset.addItem)));document.querySelectorAll('[data-remove-item]').forEach(b=>b.onclick=async()=>{const [id,ref]=b.dataset.removeItem.split('|');if(!confirm(`Remove ${ref} and its dependencies?`))return;await api(`/api/projects/${project.id}/delivery-plan-candidates/${id}/items/${ref}`,{method:'DELETE'});render()});document.querySelectorAll('[data-edit-deps]').forEach(b=>{const c=candidates.find(x=>x.id===b.dataset.editDeps);b.onclick=()=>modal(`<h2>Edit dependencies</h2><p>Cycles and unknown refs are rejected.</p><label>Dependencies JSON<textarea name="deps" class="json-editor">${esc(JSON.stringify(c.content.dependencies,null,2))}</textarea></label>`,async f=>{const dependencies=JSON.parse(f.get('deps'));await api(`/api/projects/${project.id}/delivery-plan-candidates/${c.id}/dependencies`,{method:'PUT',body:JSON.stringify({dependencies})});render()})});document.querySelectorAll('[data-regen-plan]').forEach(b=>b.onclick=()=>designGenerationModal('plans',b.dataset.regenPlan));document.querySelectorAll('[data-reject-plan]').forEach(b=>b.onclick=()=>modal('<h2>Reject delivery plan</h2><label>Reason<textarea name="reason"></textarea></label>',async f=>{await api(`/api/projects/${project.id}/delivery-plan-candidates/${b.dataset.rejectPlan}:reject`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});render()}));document.querySelectorAll('[data-commit-plan]').forEach(b=>b.onclick=async()=>{if(!confirm('Commit this exact delivery-plan revision?'))return;await api(`/api/projects/${project.id}/delivery-plan-candidates/${b.dataset.commitPlan}:commit`,{method:'POST',headers:{'Idempotency-Key':key()}});toast('Delivery plan committed and readback confirmed.');render()});if($('#freeze-gate2'))$('#freeze-gate2').onclick=async()=>{if(!confirm(`Freeze Gate 2 with Requirement Baseline ${ready.requirement_baseline_id}, Solution ${ready.solution_revision_id}, and Plan ${ready.delivery_plan_revision_id}? This exact membership cannot change.`))return;const result=await api(`/api/projects/${project.id}/delivery-baselines:freeze`,{method:'POST',headers:{'Idempotency-Key':key()}});toast(`Delivery Baseline v${result.version} frozen and confirmed.`);render()}}
function addItemModal(candidateId,candidate){const req=candidate.content.items[0]?.requirement_revision_ids[0]||'',component=candidate.content.items[0]?.solution_component_refs[0]||'',ws=candidate.content.workstreams[0]?.ref||'';modal(`<h2>Add delivery item</h2><label>Ref<input name="ref" value="item-manual" required></label><label>Workstream ref<input name="workstream_ref" value="${esc(ws)}" required></label><label>Title<input name="title" required></label><label>Description<textarea name="description" required></textarea></label><label>Owner role<input name="owner_role" value="Delivery Team" required></label><label>Acceptance criterion<textarea name="criterion" required></textarea></label><label>Effort<select name="effort"><option>S</option><option selected>M</option><option>L</option><option>XL</option></select></label><label>Requirement revision ID<input name="requirement" value="${esc(req)}" required></label><label>Solution component ref<input name="component" value="${esc(component)}" required></label>`,async f=>{const x=Object.fromEntries(f);const item={ref:x.ref,workstream_ref:x.workstream_ref,title:x.title,description:x.description,owner_role:x.owner_role,acceptance_criteria:[x.criterion],effort:x.effort,requirement_revision_ids:[x.requirement],solution_component_refs:[x.component]};await api(`/api/projects/${project.id}/delivery-plan-candidates/${candidateId}/items`,{method:'POST',body:JSON.stringify({item})});render()})}

async function executionView(){const [ready,plans,items,truth,drift]=await Promise.all([api(`/api/projects/${project.id}/execution/readiness`),api(`/api/projects/${project.id}/execution/materialization-plans`),api(`/api/projects/${project.id}/execution/items`),api(`/api/projects/${project.id}/execution/truth`),api(`/api/projects/${project.id}/execution/drift`)]);const plan=plans[0];const planRows=plan?plan.items.map(i=>`<tr><td><strong>${esc(i.source_delivery_item_ref||'UNLINKED')}</strong><br>${esc(i.execution_title)}</td><td><select data-route="${i.id}" ${plan.status!=='NEEDS_REVIEW'?'disabled':''}>${['INTERNAL','PM_AGAIN','MANUAL_EXTERNAL'].map(x=>`<option ${i.target_type===x?'selected':''}>${x}</option>`).join('')}</select></td><td>${esc(i.owner_role||'Unassigned')}</td><td>${esc(i.priority)}</td><td>${esc(i.milestone_ref||'—')}</td><td>${i.warnings.map(esc).join('; ')||'—'}</td><td><span class="tag ${['BLOCKED','FAILED','UNCONFIRMED'].includes(i.status)?'red':''}">${esc(i.status)}</span>${plan.status==='NEEDS_REVIEW'?`<button class="link" data-edit-routing="${i.id}">Edit</button><button class="link danger" data-toggle-mapping="${i.id}" data-enabled="${i.enabled}">${i.enabled?'Disable':'Enable'}</button>`:''}</td></tr>`).join(''):'';const executionRows=items.map(i=>`<tr><td>${esc(i.execution_code)}</td><td>${i.source_delivery_item_id?esc(i.source_delivery_item_id):'<span class="tag warn">UNLINKED</span>'}</td><td>${esc(i.target_type)}${i.external_url?`<br><a href="${esc(i.external_url)}" target="_blank" rel="noreferrer">Open target</a>`:''}</td><td>${esc(i.owner_role||'Unassigned')}</td><td>${esc(i.status)}</td><td><span class="tag ${['ERROR','MISMATCH','UNCONFIRMED','STALE'].includes(i.reconciliation_status)?'red':''}">${esc(i.reconciliation_status)}</span></td></tr>`).join('');const driftRows=drift.map(d=>`<article class="card attention ${d.severity==='CRITICAL'?'high':''}"><div class="card-head"><span class="tag ${d.severity==='CRITICAL'?'red':'warn'}">${esc(d.drift_type)}</span><span>${esc(d.status)}</span></div><p>${esc(JSON.stringify(d.detail))}</p>${d.status==='OPEN'?`<button class="secondary" data-ack-drift="${d.id}">Acknowledge</button>`:''}</article>`).join('')||'<article class="card"><p>No execution drift detected.</p></article>';$('#view').innerHTML=`<section class="card"><div class="split"><div><p class="eyebrow">Frozen source</p><h2>Delivery Baseline ${ready.delivery_baseline_version?`v${ready.delivery_baseline_version}`:'not available'}</h2><p>${ready.ready?'Execution planning may proceed from this exact frozen source.':'Freeze Gate 2 before execution planning.'}</p></div><div class="actions"><button id="manual-plan" class="secondary" ${ready.ready||plan?'':'disabled'} ${plan?'hidden':''}>Start manual plan</button><button id="generate-materialization" ${ready.ready?'':'disabled'}>Generate AI plan</button></div></div></section><div class="stats"><div class="stat"><small>Materialized</small><strong>${truth.execution_materialization_progress.materialized}/${truth.execution_materialization_progress.total}</strong></div><div class="stat"><small>Execution health</small><strong>${esc(truth.execution_health)}</strong></div><div class="stat"><small>Binding</small><strong>${esc(truth.execution_binding_status)}</strong></div><div class="stat"><small>Open drift</small><strong>${truth.execution_drift.open}</strong></div></div>${plan?`<section class="section"><div class="split"><div><h2>Materialization plan</h2><p class="muted">${plan.ai_run_id?'AI suggestion':'Human-prepared'} · human-controlled · revision ${plan.current_revision}</p></div><div class="actions">${plan.status==='NEEDS_REVIEW'?'<button id="reject-materialization" class="danger">Reject plan</button><button id="add-materialization" class="secondary">Add mapping</button><button id="authorize-materialization">Authorize ready items</button>':''}${['AUTHORIZED','PARTIAL'].includes(plan.status)?'<button id="run-materialization">Materialize ready items</button>':''}</div></div><div class="result-strip"><span>Ready ${plan.preview.enabled-plan.preview.blocked}</span><span>Blocked ${plan.preview.blocked}</span><span>Target routes ${Object.entries(plan.preview.targets).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')}</span></div><div class="table-wrap"><table><thead><tr><th>Source / work</th><th>Target</th><th>Owner</th><th>Priority</th><th>Milestone</th><th>Warnings</th><th>Status</th></tr></thead><tbody>${planRows}</tbody></table></div></section>`:'<section class="card section"><p>No materialization plan yet. AI generation is advisory and creates no execution work; manual fallback remains available.</p></section>'}<section class="section"><div class="split"><h2>Actual execution</h2><div class="actions"><button id="add-execution" class="secondary" ${ready.ready?'':'disabled'}>Add manual work</button><button id="reconcile-execution" ${items.length?'':'disabled'}>Reconcile authoritative state</button></div></div>${items.length?`<div class="table-wrap"><table><thead><tr><th>Execution</th><th>Baseline source</th><th>Target</th><th>Owner</th><th>Status</th><th>Reconciliation</th></tr></thead><tbody>${executionRows}</tbody></table></div>`:'<article class="card"><p>No authoritative execution items exist.</p></article>'}</section><section class="section"><h2>Baseline vs actual · drift</h2><div class="grid">${driftRows}</div></section>`;bindExecutionActions(plan)}
function bindExecutionActions(plan){if($('#generate-materialization'))$('#generate-materialization').onclick=()=>modal('<h2>Generate materialization plan</h2><p>AI will preserve exact frozen lineage and propose routing. Nothing is created until human authorization.</p><label>Optional guidance<textarea name="instruction"></textarea></label>',async f=>startAI(`/api/projects/${project.id}/execution/materialization-plans:generate`,Object.fromEntries(f)));if($('#manual-plan'))$('#manual-plan').onclick=async()=>{await api(`/api/projects/${project.id}/execution/materialization-plans`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify({summary:'Human-prepared fallback execution routing plan.'})});render()};if($('#reject-materialization'))$('#reject-materialization').onclick=async()=>{if(!confirm('Reject this materialization plan? Its revision history will remain auditable.'))return;await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}:reject`,{method:'POST',body:JSON.stringify({reason:'Rejected during human execution review.'})});render()};document.querySelectorAll('[data-route]').forEach(x=>x.onchange=async()=>{try{await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}/items/${x.dataset.route}`,{method:'PATCH',body:JSON.stringify({target_type:x.value,binding_id:null})});render()}catch(e){toast(e.message,true)}});document.querySelectorAll('[data-toggle-mapping]').forEach(b=>b.onclick=async()=>{await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}/items/${b.dataset.toggleMapping}`,{method:'PATCH',body:JSON.stringify({enabled:b.dataset.enabled!=='true'})});render()});document.querySelectorAll('[data-edit-routing]').forEach(b=>{const i=plan.items.find(x=>x.id===b.dataset.editRouting);b.onclick=()=>modal(`<h2>Edit execution mapping</h2><label>Execution title<input name="execution_title" value="${esc(i.execution_title)}" required></label><label>Description<textarea name="execution_description" required>${esc(i.execution_description)}</textarea></label><label>Owner role<input name="owner_role" value="${esc(i.owner_role||'')}" required></label><label>Priority<select name="priority">${['HIGH','MEDIUM','LOW'].map(x=>`<option ${i.priority===x?'selected':''}>${x}</option>`).join('')}</select></label>`,async f=>{await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}/items/${i.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(f))});render()})});if($('#add-materialization'))$('#add-materialization').onclick=()=>manualMaterializationModal(plan);if($('#authorize-materialization'))$('#authorize-materialization').onclick=async()=>{if(!confirm('Authorize all ready mappings? Blocked mappings remain excluded and visible.'))return;await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}:authorize`,{method:'POST',headers:{'Idempotency-Key':key()}});toast('Ready execution mappings authorized.');render()};if($('#run-materialization'))$('#run-materialization').onclick=async()=>{const result=await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}:materialize`,{method:'POST',headers:{'Idempotency-Key':key()}});toast(`${result.status}: ${result.confirmed_count} confirmed, ${result.failed_count} failed, ${result.unconfirmed_count} unconfirmed, ${result.blocked_count} blocked`,result.status!=='MATERIALIZED');render()};if($('#add-execution'))$('#add-execution').onclick=manualExecutionModal;if($('#reconcile-execution'))$('#reconcile-execution').onclick=async()=>{const result=await api(`/api/projects/${project.id}/execution:reconcile`,{method:'POST',headers:{'Idempotency-Key':key()}});toast(`Reconciliation ${result.status}: ${result.drift_count} drift records`,result.status!=='SUCCEEDED');render()};document.querySelectorAll('[data-ack-drift]').forEach(b=>b.onclick=async()=>{await api(`/api/projects/${project.id}/execution/drift/${b.dataset.ackDrift}:acknowledge`,{method:'POST'});render()})}
function manualMaterializationModal(plan){const sources=plan.items.filter(x=>x.source_delivery_item_id);modal(`<h2>Add manual mapping</h2><label>Frozen delivery source<select name="source_delivery_item_id"><option value="">Unlinked</option>${sources.map(x=>`<option value="${esc(x.source_delivery_item_id)}">${esc(x.source_delivery_item_ref)} · ${esc(x.execution_title)}</option>`).join('')}</select></label><label>Execution title<input name="execution_title" required></label><label>Description<textarea name="execution_description" required></textarea></label><label>Owner role<input name="owner_role" required></label><label>Acceptance hint<textarea name="acceptance_hint" required></textarea></label>`,async f=>{const body=Object.fromEntries(f);if(!body.source_delivery_item_id)body.source_delivery_item_id=null;await api(`/api/projects/${project.id}/execution/materialization-plans/${plan.id}/items`,{method:'POST',body:JSON.stringify(body)});render()})}
function manualExecutionModal(){modal('<h2>Add manual execution work</h2><p>Work without a frozen delivery link will be explicitly marked UNLINKED.</p><label>Title<input name="title" required></label><label>Description<textarea name="description" required></textarea></label><label>Owner role<input name="owner_role" required></label><label>Priority<select name="priority"><option>HIGH</option><option selected>MEDIUM</option><option>LOW</option></select></label>',async f=>{await api(`/api/projects/${project.id}/execution/items`,{method:'POST',body:JSON.stringify(Object.fromEntries(f))});render()})}

async function validationView(){const [ready,scopes,items,evidence]=await Promise.all([api(`/api/projects/${project.id}/qa/readiness`),api(`/api/projects/${project.id}/qa-scopes`),api(`/api/projects/${project.id}/validation-items`),api(`/api/projects/${project.id}/evidence`)]);const scope=scopes[0],active=scope?.items.filter(x=>x.candidate_status==='ACTIVE')||[],latest=items.filter(x=>x.candidate_status==='ACTIVE');const counts={PASS:0,FAIL:0,BLOCKED:0,SKIPPED:0,NOT_RUN:0};latest.forEach(x=>counts[x.latest_result?.result||'NOT_RUN']++);const coverage={};latest.forEach(i=>i.requirement_revision_ids.forEach(r=>{const c=coverage[r]||(coverage[r]={items:0,pass:0,evidence:0});c.items++;if(i.latest_result?.result==='PASS')c.pass++;c.evidence+=i.valid_evidence_count}));const rows=(scope?.items||[]).map(i=>`<tr><td><strong>${esc(i.validation_code)}</strong><br>${esc(i.title)}${i.origin==='AI'?'<br><small>AI candidate</small>':'<br><small>Human-authored</small>'}</td><td>${esc(i.target_type)}<br><span class="tag ${['BLOCKED','FAILED','UNCONFIRMED'].includes(i.materialization_status)?'red':''}">${esc(i.materialization_status)}</span></td><td>${i.requirement_revision_ids.map(esc).join('<br>')}</td><td>${esc(i.latest_result?.result||'NOT RUN')}<br><small>${i.valid_evidence_count} evidence</small></td><td><div class="actions">${['AI_CANDIDATE','HUMAN_REVIEWED'].includes(scope.status)&&i.candidate_status==='ACTIVE'?`<button class="link" data-edit-validation="${i.id}">Edit</button><button class="link danger" data-reject-validation="${i.id}">Reject</button>`:''}${i.candidate_status==='ACTIVE'&&i.materialization_status==='CONFIRMED'?`<button class="secondary" data-result="${i.id}">Record result</button><button class="secondary" data-evidence="${i.id}">Attach evidence</button>`:''}</div></td></tr>`).join('');$('#view').innerHTML=`<section class="card"><div class="split"><div><p class="eyebrow">Execution Truth → QA Scope</p><h2>${scope?`${esc(scope.qa_code)} rev ${scope.current_revision} — ${esc(scope.status)}`:'No QA Scope'}</h2><p>${scope?esc(scope.summary):(ready.ready?'Generate an advisory scope or start manually.':'Gate 2 and healthy Execution Truth are required.')}</p></div><div class="actions">${!scope?`<button id="manual-qa" class="secondary" ${ready.ready?'':'disabled'}>Start manual scope</button><button id="generate-qa" ${ready.ready?'':'disabled'}>Generate QA Scope</button>`:''}${scope&&['AI_CANDIDATE','HUMAN_REVIEWED'].includes(scope.status)?'<button id="add-validation" class="secondary">Add Validation</button><button id="commit-qa">Commit QA Scope</button>':''}${scope?.status==='COMMITTED'?'<button id="materialize-qa">Materialize validations</button>':''}</div></div></section><div class="stats"><div class="stat"><small>Required validations</small><strong>${latest.filter(x=>x.required_for_acceptance).length}</strong></div><div class="stat"><small>PASS</small><strong class="truth-ok">${counts.PASS}</strong></div><div class="stat"><small>FAIL</small><strong class="truth-blocked">${counts.FAIL}</strong></div><div class="stat"><small>BLOCKED</small><strong>${counts.BLOCKED}</strong></div><div class="stat"><small>NOT RUN</small><strong>${counts.NOT_RUN}</strong></div><div class="stat"><small>Evidence missing</small><strong>${latest.filter(x=>x.required_for_acceptance&&x.latest_result?.result==='PASS'&&x.valid_evidence_count===0).length}</strong></div></div><section class="section"><h2>Validation items</h2>${scope?`<div class="table-wrap"><table><thead><tr><th>Validation</th><th>Target</th><th>Requirements</th><th>Result / evidence</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<article class="card"><p>No validation items.</p></article>'}</section><section class="section"><h2>Requirement coverage</h2><div class="grid">${Object.entries(coverage).map(([r,c])=>`<article class="card"><span class="tag">${esc(r)}</span><h3>${c.pass===c.items?'Validated: YES':'Validated: PARTIAL'}</h3><p>${c.pass}/${c.items} PASS · ${c.evidence} evidence</p></article>`).join('')||'<article class="card"><p>Coverage appears after QA generation.</p></article>'}</div></section><section class="section"><h2>Evidence truth</h2><div class="grid">${evidence.map(e=>`<article class="card"><span class="tag">${esc(e.classification)} · ${esc(e.evidence_type)}</span><h3>${esc(e.evidence_code)} · ${esc(e.status)}</h3><p>${esc(e.title)}</p><small>Result ${esc(e.validation_result_id||'—')} · SHA-256 ${esc(e.content_sha256)}</small></article>`).join('')||'<article class="card"><p>No evidence captured.</p></article>'}</div></section>`;bindValidationActions(scope,active)}
function bindValidationActions(scope,items){if($('#generate-qa'))$('#generate-qa').onclick=()=>modal('<h2>Generate QA Scope</h2><p>AI proposes grounded validation coverage. It cannot commit results or approve Gate 3.</p><label>Optional guidance<textarea name="instruction"></textarea></label>',async f=>{const r=await api(`/api/projects/${project.id}/qa-scopes:generate`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});toast(r.status==='FAILED'?`${r.failure_code}: ${r.message}`:'QA Scope ready for human review.',r.status==='FAILED');render()});if($('#manual-qa'))$('#manual-qa').onclick=async()=>{await api(`/api/projects/${project.id}/qa-scopes`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify({summary:'Human-prepared QA scope grounded in frozen baselines and Execution Truth.'})});render()};if($('#commit-qa'))$('#commit-qa').onclick=async()=>{if(!confirm('Commit this exact QA Scope revision and coverage?'))return;await api(`/api/projects/${project.id}/qa-scopes/${scope.id}:commit`,{method:'POST',headers:{'Idempotency-Key':key()}});toast('QA Scope committed.');render()};if($('#materialize-qa'))$('#materialize-qa').onclick=async()=>{const r=await api(`/api/projects/${project.id}/qa-scopes/${scope.id}:materialize`,{method:'POST',headers:{'Idempotency-Key':key()}});toast(`${r.status}: ${r.confirmed_count} confirmed`,r.status!=='CONFIRMED');render()};document.querySelectorAll('[data-edit-validation]').forEach(b=>{const i=items.find(x=>x.id===b.dataset.editValidation);b.onclick=()=>modal(`<h2>Edit validation</h2><label>Title<input name="title" value="${esc(i.title)}" minlength="8" required></label><label>Owner role<input name="owner_role" value="${esc(i.owner_role)}" required></label><label>Priority<select name="priority">${['HIGH','MEDIUM','LOW'].map(x=>`<option ${x===i.priority?'selected':''}>${x}</option>`).join('')}</select></label>`,async f=>{await api(`/api/projects/${project.id}/qa-scopes/${scope.id}/items/${i.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(f))});render()})});document.querySelectorAll('[data-reject-validation]').forEach(b=>b.onclick=async()=>{await api(`/api/projects/${project.id}/qa-scopes/${scope.id}/items/${b.dataset.rejectValidation}:reject`,{method:'POST'});render()});if($('#add-validation'))$('#add-validation').onclick=()=>manualValidationModal(scope,items[0]);document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>resultModal(items.find(x=>x.id===b.dataset.result)));document.querySelectorAll('[data-evidence]').forEach(b=>b.onclick=()=>evidenceModal(items.find(x=>x.id===b.dataset.evidence)))}
function manualValidationModal(scope,seed){modal(`<h2>Add manual validation</h2><label>Area<input name="area" value="Functional" required></label><label>Title<input name="title" minlength="8" required></label><label>Objective<textarea name="objective" minlength="20" required></textarea></label><label>Validation method<textarea name="validation_method" minlength="20" required></textarea></label><label>Expected result<textarea name="expected_result" minlength="15" required></textarea></label><label>Requirement revision IDs (comma-separated)<input name="requirements" value="${esc(seed?.requirement_revision_ids.join(',')||'')}" required></label><label>Acceptance criteria refs (JSON)<textarea name="criteria" required>${esc(JSON.stringify(seed?.acceptance_criteria_refs||[]))}</textarea></label><label>Delivery item IDs (comma-separated)<input name="delivery" value="${esc(seed?.delivery_item_ids.join(',')||'')}"></label><label>Execution item IDs (comma-separated)<input name="execution" value="${esc(seed?.execution_item_ids.join(',')||'')}"></label>`,async f=>{const x=Object.fromEntries(f),split=v=>v.split(',').map(y=>y.trim()).filter(Boolean);const body={area:x.area,title:x.title,objective:x.objective,validation_method:x.validation_method,expected_result:x.expected_result,requirement_revision_ids:split(x.requirements),acceptance_criteria_refs:JSON.parse(x.criteria),delivery_item_ids:split(x.delivery),execution_item_ids:split(x.execution),required_evidence_types:['REPORT']};await api(`/api/projects/${project.id}/qa-scopes/${scope.id}/items`,{method:'POST',body:JSON.stringify(body)});render()})}
function resultModal(item){modal(`<h2>Record append-only result · ${esc(item.validation_code)}</h2><label>Result<select name="result"><option>PASS</option><option>FAIL</option><option>BLOCKED</option><option>SKIPPED</option></select></label><label>Observed result<textarea name="observed_result" minlength="5" required></textarea></label><label>Notes<textarea name="notes"></textarea></label>`,async f=>{await api(`/api/projects/${project.id}/validation-items/${item.id}/results`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});render()})}
function evidenceModal(item){modal(`<h2>Attach evidence · ${esc(item.validation_code)}</h2><label>Classification<select name="classification"><option>TEST</option><option>INTERNAL</option><option>CUSTOMER</option></select></label><label>Type<select name="evidence_type"><option>REPORT</option><option>RECORD</option><option>LOG</option><option>SCREENSHOT</option><option>API_RESPONSE</option><option>DOCUMENT</option><option>APPROVAL</option><option>LINK</option><option>OTHER</option></select></label><label>Title<input name="title" required></label><label>Description<textarea name="description" minlength="5" required></textarea></label><label>Evidence content<textarea name="content_text" required></textarea></label>`,async f=>{const body=Object.fromEntries(f);body.validation_item_id=item.id;body.validation_result_id=item.latest_result?.id;body.execution_item_id=item.execution_item_ids[0]||null;body.requirement_revision_ids=item.requirement_revision_ids;await api(`/api/projects/${project.id}/evidence`,{method:'POST',body:JSON.stringify(body)});render()})}

async function acceptanceView(){const [r,packages,finals]=await Promise.all([api(`/api/projects/${project.id}/acceptance/readiness`),api(`/api/projects/${project.id}/acceptance-packages`),api(`/api/projects/${project.id}/final-acceptances`)]);const p=packages[0],final=finals[0];$('#view').innerHTML=`<section class="card"><div class="split"><div><p class="eyebrow">Deterministic Gate 3</p><h2>Final Acceptance</h2><p><strong class="${r.ready?'truth-ok':'truth-blocked'}">${esc(final?'ACCEPTED':r.status)}</strong></p></div><div class="actions">${!final?'<button id="manual-package" class="secondary">Prepare manual package</button><button id="generate-package">Generate Acceptance Package</button>':''}${r.ready&&!final?'<button id="final-accept">Accept Project Delivery</button>':''}</div></div></section><div class="stats"><div class="stat"><small>Requirement coverage</small><strong>${r.requirement_summary?.covered||0}/${r.requirement_summary?.total||0}</strong></div><div class="stat"><small>Required validation</small><strong>${r.validation_summary?.pass||0}/${r.validation_summary?.total||0}</strong></div><div class="stat"><small>Evidence</small><strong>${r.evidence_summary?.valid||0}</strong><span>${r.evidence_summary?.missing||0} missing</span></div><div class="stat"><small>Critical drift</small><strong>${r.blocking_items?.includes('UNRESOLVED_CRITICAL_DRIFT')?1:0}</strong></div></div>${r.blocking_items?.length?`<section class="section"><h2>Why acceptance is blocked</h2><div class="grid">${r.blocking_items.map(x=>`<article class="card attention high"><span class="tag red">${esc(x)}</span></article>`).join('')}</div></section>`:'<section class="card section"><h2>All required validation conditions are satisfied.</h2><p>The exact current Acceptance Package can be accepted by the human project owner.</p></section>'}<section class="section"><h2>Acceptance packages</h2><div class="grid">${packages.map(x=>`<article class="card"><span class="tag">v${x.version} · ${esc(x.status)}</span><h3>${esc(x.recommendation)}</h3><p>${esc(x.executive_summary)}</p><p><strong>Critical blockers:</strong> ${x.critical_blockers.map(esc).join(', ')||'None'}</p><p><strong>Missing evidence:</strong> ${x.missing_evidence.length}</p><small>Provenance: ${esc(x.generated_by)}</small></article>`).join('')||'<article class="card"><p>No Acceptance Package yet.</p></article>'}</div></section>${final?`<section class="card section"><span class="tag">${esc(final.acceptance_code)} · ACCEPTED</span><h2>Immutable Final Acceptance</h2><p>${esc(final.acceptance_comment)}</p><small>${final.validation_result_ids.length} exact results · ${final.evidence_ids.length} exact evidence records · membership ${esc(final.membership_hash)}</small></section>`:''}`;if($('#generate-package'))$('#generate-package').onclick=()=>modal('<h2>Generate Acceptance Package</h2><p>AI summarizes authoritative truth. It cannot change readiness or accept delivery.</p><label>Optional guidance<textarea name="instruction"></textarea></label>',async f=>{const x=await api(`/api/projects/${project.id}/acceptance-packages:generate`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});toast(x.status==='FAILED'?`${x.failure_code}: ${x.message}`:'Acceptance Package generated.',x.status==='FAILED');render()});if($('#manual-package'))$('#manual-package').onclick=()=>modal('<h2>Prepare manual Acceptance Package</h2><label>Executive summary<textarea name="executive_summary" minlength="20" required></textarea></label><label>Recommendation basis<textarea name="recommendation_basis" minlength="20" required></textarea></label><p>Readiness remains deterministic; this package makes no AI recommendation.</p>',async f=>{await api(`/api/projects/${project.id}/acceptance-packages`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify(Object.fromEntries(f))});render()});if($('#final-accept'))$('#final-accept').onclick=()=>finalAcceptanceModal(r,p)}
function finalAcceptanceModal(r,p){modal(`<h2>Accept Project Delivery</h2><p>You are accepting this exact immutable membership:</p><ul><li>Requirement Baseline v${r.requirement_baseline_version} · ${esc(r.requirement_baseline_id)}</li><li>Delivery Baseline v${r.delivery_baseline_version} · ${esc(r.delivery_baseline_id)}</li><li>QA Scope ${esc(r.qa_scope_code)} rev ${r.qa_scope_revision}</li><li>${r.result_ids.length} validation results</li><li>${r.evidence_ids.length} evidence records</li><li>0 unresolved deterministic blockers</li></ul><label>Acceptance comment<textarea name="acceptance_comment" minlength="10" required></textarea></label>`,async f=>{if(!confirm('Final Acceptance is immutable. Confirm this exact membership?'))return;await api(`/api/projects/${project.id}/final-acceptance`,{method:'POST',headers:{'Idempotency-Key':key()},body:JSON.stringify({acceptance_package_id:p.id,acceptance_comment:f.get('acceptance_comment')})});toast('Project delivery accepted and readback confirmed.');render()})}

async function auditView(){const rows=await api(`/api/projects/${project.id}/audit`);$('#view').innerHTML=`<h2>Audit and provenance</h2><div class="section">${rows.map(x=>`<article class="card"><div class="card-head"><span class="tag">${esc(x.actor_type)}</span><small>${esc(x.created_at)}</small></div><h3>${esc(x.action)}</h3><p>${esc(x.target_type)} · ${esc(x.target_id||'')}</p><small>Actor: ${esc(x.actor_id)} · Result: ${esc(x.result)}</small></article>`).join('')}</div>`}
function modal(html,save){const d=$('#dialog'),form=$('#dialog-form');$('#dialog-body').innerHTML=html;d.showModal();form.onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();try{await save(new FormData(form));d.close()}catch(x){toast(x.message,true)}}}
boot();
